        else: txt=str(c)[:160]
        print(f"   content: {txt[:160]!r}")
    elif r=='custom':
        c=m.get('content')
        print(f"   content: {str(c)[:160]!r}")
    else:
        print(f"   content: {str(m.get('content'))[:160]!r}")
