"""Build the M1 replay set: convert host-recorded bonsai-garden traffic into
OpenAI-chat JSONLs (agent.jsonl, mem.jsonl) plus replay_manifest.json.

Agent: 30 turns across the 6 inventory tasks x 3 variants (baseline/mem0 r0-2),
picked by a stable hash of the task prompt (round-robin across variants). Each
record is a full per-step conversation (system + user task + memory recalls +
tool round-trips), matching how pi actually saw each LLM request.

Mem: 12 additive-extraction calls from the mem0 history DBs (steps 0-2 of
mem0-r0/r1/r2). Each record carries the prompt exactly as tools.js assembled
it (system = ADDITIVE_EXTRACTION_PROMPT, messages = the last K conversation
messages before the cutoff), and the ground truth (extracted memories) is
taken from memory_history so the n-gram scorer can measure recall.

Replay records are named <run>/<step>/<turn>. agent.jsonl = <run>/<step>/<i>
with i = LLM-request index; mem.jsonl = <run>/<step>/<extract_i> (1-based).
The manifest is committed; raw replay JSONLs are git-ignored.
"""
from __future__ import annotations

import argparse, json, pathlib, random, sqlite3
from datetime import datetime, timezone

RECON = pathlib.Path(__file__).resolve().parent.parent / "bench/results/2026-10-12/m1-ngram/recon"
HOST_BASE = "/home/josiah/Projects/bonsai-garden/evals/results/2026-10-11-baseline-mem0/runs"
REPLAY = pathlib.Path(__file__).resolve().parent / ".replay"

ROLE_MAP = {"user": "user", "custom": "user", "system": "system"}
# pi tool names that are never exposed to the LLM as calls (already resolved by
# the harness) - not present in these records, kept for safety.
SKIP_ROLES = set()


def ts_ms(s):
    return int(s) if isinstance(s, (int, float)) else (
        datetime.fromisoformat(str(s).replace("Z", "+00:00")).timestamp() * 1000)


def system_text(m):
    sections = m.get("sections", {})
    return "\n\n".join(str(v) for v in sections.values()), True
# Note: system_prompt_exact is only claimed for turns whose system message is the
# first-request one (see manifest); the join order is the recorded sections order.


def blocks_text(content):
    if isinstance(content, str):
        return content
    out = []
    for b in content:
        if b.get("type") == "text":
            out.append(b.get("text", ""))
    return "".join(out)


def read_events(path):
    s, msgs = None, None
    for line in open(path):
        e = json.loads(line)
        if e["type"] == "session":
            s = e["timestamp"]
        elif e["type"] == "agent_end":
            msgs = e["messages"]
    return s, msgs


def to_openai(m):
    r = m["role"]
    if r == "system":
        return {"role": "system", "content": system_text(m)[0]}
    if r in ("user", "custom"):  # mem0-recall "custom" arrives as a user message
        return {"role": "user", "content": blocks_text(m["content"])}
    if r == "toolResult":
        return {"role": "tool", "tool_call_id": m["toolCallId"],
                "content": blocks_text(m["content"])}
    if r == "assistant":  # reasoning dropped, as pi does
        out = {"role": "assistant", "content": "".join(
            b.get("text", "") for b in m["content"] if b.get("type") == "text")}
        calls = [b for b in m["content"] if b.get("type") == "toolCall"]
        if calls:
            out["tool_calls"] = [{"id": c["id"], "type": "function",
                                  "function": {"name": c["name"],
                                               "arguments": (c["arguments"]
                                                             if isinstance(c["arguments"], str)
                                                             else json.dumps(c["arguments"]))}
                                 } for c in calls]
        return out
    raise ValueError("unknown role " + r)


def agent_turns(msgs):
    """Split recorded messages into per-LLM-request units. Each unit starts
    with an assistant message that carries the tool_calls that unit asked for,
    followed by their toolResult messages (which pi feeds as the next turn's
    prefix). Returns a list of per-unit message lists."""
    units = []
    cur = []
    for m in msgs:
        r = m["role"]
        if r == "assistant":
            # an assistant message closes the previous unit (if any) and opens
            # a new one.
            if cur:
                units.append(cur)
            cur = [m]
        else:
            cur.append(m)
    if cur:
        units.append(cur)
    return units


def tool_list(sysmsg):
    return [{"type": "function",
             "function": {"name": t["name"], "description": t["description"],
                          "parameters": t["parameters"]}}
            for t in sysmsg.get("toolsAdded", [])]


def load_additive(path):
    txt = path.read_text(encoding="utf-8")
    marker = "var ADDITIVE_EXTRACTION_PROMPT = `"
    a = txt.index(marker) + len(marker)
    # The template literal is closed by the NEXT bare backtick (the recon dump
    # has no trailing semicolon after the closer); rstrip the trailing newline.
    # Non-ASCII appears as \uXXXX escapes (JS source); decode them.
    b = txt.index("`", a)
    raw = txt[a:b].rstrip("\n")
    return re.sub(r"\\u([0-9a-fA-F]{4})", lambda m: chr(int(m.group(1), 16)), raw)


import re  # needed by load_additive


def existing_memories(con, cols, cutoff, limit=10):
    tcol = next((c for c in ("new_memory", "new_value", "text", "memory") if c in cols), None)
    ecol = "event" if "event" in cols else None
    if not tcol:
        return [], False
    rows = [dict(r) for r in con.execute("SELECT * FROM memory_history ORDER BY rowid")]
    out, kept = [], []
    for r in rows:
        ts = parse_ts(r.get("created_at")) if "created_at" in cols else None
        if ts is not None and cutoff is not None and ts >= cutoff:
            continue
        t = r.get(tcol)
        if t and t not in [x.get(tcol) for x in kept]:
            kept.append(r)
    kept = sorted(kept, key=lambda r: (
        parse_ts(r.get("created_at")) if "created_at" in cols else 0,
        r.get("rowid", 0) or 0), reverse=True)
    for r in kept[:limit]:
        out.append(f'- ({"UNTRUSTED MEMORY DATA"} "{(r.get(tcol) or "")}"')
    return out, ecol is not None


def last_k(con, cols, cutoff, k=10):
    """Last K conversation messages before `cutoff` (mem0 auto-capture context).
    Uses the messages table from memory/mem0-history.db."""
    if not {"role", "content"} <= set(cols):
        return []
    rows = [dict(r) for r in con.execute("SELECT * FROM messages ORDER BY rowid")]
    out = []
    for r in rows:
        ts = parse_ts(r.get("created_at")) if "created_at" in cols else None
        if cutoff is not None and ts is not None and ts >= cutoff:
            continue
        out.append(f"{r['role']}: {r['content']}")
    return out[-k:]


def parse_ts(s):
    if s is None:
        return None
    try:
        return datetime.fromisoformat(str(s).replace("Z", "+00:00")).timestamp()
    except ValueError:
        return None


def db_tables(db):
    con = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    con.row_factory = sqlite3.Row
    info = {}
    for t in ("memory_history", "messages"):
        info[t] = [r["name"] for r in con.execute(f"PRAGMA table_info({t})")]
    return con, info


def main():
    ap = argparse.ArgumentParser(description="build M1 replay set")
    ap.add_argument("--dry-run", action="store_true", help="print plan, write nothing")
    ap.add_argument("--mem-max", type=int, default=12, help="max mem0 records")
    args = ap.parse_args()

    inv = json.loads((RECON / "inventory.json").read_text())
    additive = load_additive(RECON / "mem0_extract_src.txt")

    steps = []
    for run in inv["runs"]:
        name = run["variant"] if "variant" in run else run["name"]
        for st in run.get("steps", []):
            events = read_events(pathlib.Path(st["events_file"]))
            ts, msgs = events
            steps.append({
                "name": name, "step": st.get("step", 0), "session_ts": ts,
                "msgs": msgs, "task": st.get("task", ""), "n_msgs": len(msgs),
                "mem0_dbs": st.get("mem0_dbs", {}), "tap_total": st.get("tap_record_total", 0),
            })
    print(f"loaded {len(steps)} steps")

    # pick ~30 agent turns: stable hash of task prompt, round-robin variants
    rng = random.Random(20261012)
    seed = hash("".join(s["task"]) + str(s["name"]))
    order = sorted(range(len(steps)), key=lambda i: (seed + i) % len(steps))
    picks = []
    for i in order:
        s = steps[i]
        if any(p["name"] == s["name"] for p in picks):
            continue
        picks.append(s)
        if len(picks) >= 30:
            break
    picks.sort(key=lambda s: (s["name"], s["step"]))
    print(f"picked {len(picks)} agent steps (names: {sorted({p['name'] for p in picks})})")

    # mem0 records: first mem-max from mem0 runs (steps 0,1,2 of r0-r2)
    mem_steps = []
    for s in steps:
        if s["name"] in ("mem0-r0", "mem0-r1", "mem0-r2") and s["step"] <= 2:
            mem_steps.append(s)
    mem_records = []
    for s in mem_steps:
        for db_path, _label in s["mem0_dbs"].items():
            if not pathlib.Path(HOST_BASE + "/" + db_path).is_dir():
                continue
            con, info = db_tables(HOST_BASE + "/" + db_path)
            mh_cols = info.get("memory_history", [])
            msg_cols = info.get("messages", [])
            cutoff = None
            for r in [dict(x) for x in con.execute("SELECT * FROM memory_history ORDER BY rowid DESC")][:5]:
                ct = parse_ts(r.get("created_at")) if "created_at" in r.keys() else None
                if ct and (cutoff is None or ct > cutoff):
                    cutoff = ct
            existing, ec = existing_memories(con, mh_cols, cutoff)
            msgs = last_k(con, msg_cols, cutoff)
            mem_records.append({
                "id": f"{s['name']}/{s['step']}/{len(mem_records) + 1}",
                "run": s["name"], "step": s["step"], "session_ts": s["session_ts"],
                "cutoff": cutoff, "existing": existing,
                "new_msgs": msgs,
                "existing_count": len(existing), "n_new_msgs": len(msgs),
            })
            if len(mem_records) >= args.mem_max:
                break
        if len(mem_records) >= args.mem_max:
            break
    print(f"built {len(mem_records)} mem records (mem0 runs, first {args.mem_max})")

    if args.dry_run:
        print("dry-run: would write",
              [f for f in (REPLAY / "agent.jsonl", REPLAY / "mem.jsonl", REPLAY / "replay_manifest.json")])
        return

    REPLAY.mkdir(parents=True, exist_ok=True)

    # agent.jsonl
    with open(REPLAY / "agent.jsonl", "w") as fh:
        for s in picks:
            units = agent_turns(s["msgs"])
            sysmsg = [m for m in s["msgs"] if m.get("role") == "system"][0]
            tool_l = tool_list(sysmsg)
            existing, _ = existing_memories(sysmsg, None, None)  # not needed
            for i, u in enumerate(units):
                rec = {
                    "id": f"{s['name']}/{s['step']}/{i}",
                    "run": s["name"], "step": s["step"], "task": s["task"],
                    "session_ts": s["session_ts"], "n_messages": len(u),
                    "messages": [to_openai(m) for m in u],
                    "tool_list": tool_l,
                    "system_prompt_exact": s.get("is_first", False),
                }
                fh.write(json.dumps(rec) + "\n")
    print(f"wrote {REPLAY / 'agent.jsonl'} with {sum(1 for _ in open(REPLAY / 'agent.jsonl'))} lines")

    # mem.jsonl
    with open(REPLAY / "mem.jsonl", "w") as fh:
        for mr in mem_records:
            rec = {
                "id": mr["id"], "run": mr["run"], "step": mr["step"],
                "session_ts": mr["session_ts"], "cutoff": mr["cutoff"],
                "system": additive,
