    with open(REPLAY / "mem.jsonl", "w") as fh:
        for mr in mem_records:
            rec = {
                "id": mr["id"], "run": mr["run"], "step": mr["step"],
                "session_ts": mr["session_ts"], "cutoff": mr["cutoff"],
                "system": additive,
                "messages": [{"role": "user", "content":
                               json.dumps({"existing_memories": mr["existing"],
                                          "new_msgs": mr["new_msgs"],
                                          "memory": []})}
                             ],
                "expected_extract": mr["existing"][:20],
                "existing_count": mr["existing_count"],
            }
            fh.write(json.dumps(rec) + "\n")
    print(f"wrote {REPLAY / 'mem.jsonl'} with {sum(1 for _ in open(REPLAY / 'mem.jsonl'))} lines")

    manifest = {
        "run_id": "m1-ngram-replay-set",
        "built": datetime.now(timezone.utc).isoformat(),
        "agent": {
            "n_records": len(picks),
