            "selection": "stable-hash round-robin over task prompt, 1 turn per run/variant",
            "system_prompt_exact": True,
            "system_prompt_note": "agent system prompt = sections from the recorded system message joined by blank lines",
            "tool_list": "from pi system message toolsAdded (read/write/edit/bash + mem0_memory)",
        },
        "mem": {
            "n_records": len(mem_records),
            "source_runs": sorted({r["run"] for r in mem_records}),
            "existing_memories": "from memory_history before cutoff",
            "new_msgs": "last K from messages before cutoff (K=10)",
        },
        "files": {"agent": "bench/.replay/agent.jsonl",
                  "mem": "bench/.replay/mem.jsonl",
                  "manifest": "bench/.replay/replay_manifest.json"},
    }
    (REPLAY / "replay_manifest.json").write_text(json.dumps(manifest, indent=2))
    print(f"wrote {REPLAY / 'replay_manifest.json'}")
